from collections import deque


def normalize(cells):
    minr = min(r for r, c in cells)
    minc = min(c for r, c in cells)
    return frozenset((r - minr, c - minc) for r, c in cells)


def components(grid, color):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            out.append(cells)
    return out


def transform(grid):
    out = [row[:] for row in grid]
    templates = {}
    for color in range(2, 10):
        for cells in components(grid, color):
            templates.setdefault(normalize(cells), color)
    for cells in components(grid, 1):
        color = templates.get(normalize(cells))
        if color is not None:
            for r, c in cells:
                out[r][c] = color
    return out
